<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{CmsPage,CmsPageSection}; use App\Enums\{CmsPageStatus,CmsPageType,CmsPageSectionType}; use App\Services\CmsPageService; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View; use Illuminate\Support\Facades\DB;
class CmsPageController extends Controller { public function index(Request $r):View{$q=CmsPage::query()->when($r->filled('q'),fn($q)=>$q->where(fn($x)=>$x->where('title','like','%'.$r->q.'%')->orWhere('slug','like','%'.$r->q.'%')))->when($r->status,fn($q,$s)=>$q->where('status',$s))->when($r->type,fn($q,$t)=>$q->where('page_type',$t))->latest()->paginate(20)->withQueryString();return view('admin.pages.index',['pages'=>$q,'types'=>CmsPageType::cases(),'filters'=>$r->only(['q','status','type'])]);} public function create():View{return view('admin.pages.form',['page'=>new CmsPage(['page_type'=>CmsPageType::Standard,'status'=>CmsPageStatus::Draft]),'types'=>CmsPageType::cases()]);} public function store(Request $r,CmsPageService $s):RedirectResponse{$d=$this->valid($r);$page=DB::transaction(function()use($r,$s,$d){$p=CmsPage::create($d+['slug'=>$s->slug($d['slug']??$d['title']),'created_by'=>$r->user()->id,'updated_by'=>$r->user()->id]);$this->sections($p,$r);return $p;});return redirect()->route('admin.pages.edit',$page)->with('status','Page created.');} public function edit(CmsPage $page):View{return view('admin.pages.form',['page'=>$page->load('sections.faqItems'),'types'=>CmsPageType::cases()]);} public function update(Request $r,CmsPage $page,CmsPageService $s):RedirectResponse{$d=$this->valid($r);DB::transaction(function()use($r,$s,$d,$page){$page->update($d+['slug'=>$s->slug($d['slug']??$d['title'],$page),'updated_by'=>$r->user()->id]);$page->sections()->delete();$this->sections($page,$r);});return back()->with('status','Page updated.');} public function publish(Request $r,CmsPage $p):RedirectResponse{$p->update(['status'=>CmsPageStatus::Published,'updated_by'=>$r->user()->id]);return back()->with('status','Page published.');} public function unpublish(Request $r,CmsPage $p):RedirectResponse{$p->update(['status'=>CmsPageStatus::Draft,'updated_by'=>$r->user()->id]);return back()->with('status','Page unpublished.');} public function preview(CmsPage $page):View{return view('storefront.pages.show',['page'=>$page->load('sections.faqItems'),'preview'=>true]);} private function valid(Request $r):array{$d=$r->validate(['title'=>['required','string','max:160'],'slug'=>['nullable','string','max:100','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/'],'page_type'=>['required','in:standard,legal,help,contact'],'excerpt'=>['nullable','string','max:500'],'seo_title'=>['nullable','string','max:160'],'seo_description'=>['nullable','string','max:255'],'status'=>['required','in:draft,published'],'published_at'=>['nullable','date'],'show_in_header'=>['nullable','boolean'],'show_in_footer'=>['nullable','boolean'],'sort_order'=>['nullable','integer','min:0'],'sections'=>['nullable','array','max:24'],'sections.*.type'=>['required','in:text,image_text,faq,callout'],'sections.*.title'=>['nullable','string','max:160'],'sections.*.content'=>['nullable','string','max:10000'],'sections.*.settings'=>['nullable','array'],'sections.*.settings.image'=>['nullable','string','max:255'],'sections.*.settings.image_alt'=>['nullable','string','max:160'],'sections.*.settings.image_position'=>['nullable','in:left,right'],'sections.*.settings.cta_label'=>['nullable','string','max:80'],'sections.*.settings.cta_url'=>['nullable','url:http,https','max:255'],'sections.*.settings.theme'=>['nullable','in:default,muted,accent'],'sections.*.faq_items'=>['nullable','array','max:30'],'sections.*.faq_items.*.question'=>['required','string','max:255'],'sections.*.faq_items.*.answer'=>['required','string','max:5000']]);if($d['status']==='published'&&!collect($d['sections']??[])->contains(fn($x)=>filled($x['content']??null)||!empty($x['faq_items']??[])))throw \Illuminate\Validation\ValidationException::withMessages(['sections'=>'Published pages require meaningful content.']);return $d;} private function sections(CmsPage $p,Request $r):void{foreach($r->input('sections',[]) as $i=>$d){$s=$p->sections()->create(['type'=>$d['type'],'title'=>$d['title']??null,'content'=>$d['content']??null,'settings'=>array_intersect_key($d['settings']??[],array_flip(['image','image_alt','image_position','cta_label','cta_url','theme'])),'sort_order'=>($i+1)*10]);foreach($d['faq_items']??[] as $j=>$f)$s->faqItems()->create(['question'=>$f['question'],'answer'=>$f['answer'],'sort_order'=>($j+1)*10]);}} }
